package com.railflow.yardops.service;
import com.railflow.yardops.domain.*; import com.railflow.yardops.repository.*; import io.micrometer.core.instrument.Counter; import io.micrometer.core.instrument.MeterRegistry; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class EventIngestionService { private static final Logger log=LoggerFactory.getLogger(EventIngestionService.class); private final ScanEventRepository events; private final RailcarRepository railcars; private final AlertRepository alerts; private final AlertRuleEngine rules; private final Counter eventCounter; public EventIngestionService(ScanEventRepository events,RailcarRepository railcars,AlertRepository alerts,AlertRuleEngine rules,MeterRegistry metrics){this.events=events;this.railcars=railcars;this.alerts=alerts;this.rules=rules;this.eventCounter=metrics.counter("railflow.events.ingested");} @Transactional public ScanEvent ingest(ScanEvent event){ScanEvent saved=events.save(event);eventCounter.increment();Railcar car=railcars.findByCarNumber(event.getCarNumber()).orElse(null);if(car!=null)car.updateLocation(event.getYardCode());OperationalAlert alert=rules.evaluate(event,car);if(alert!=null){alerts.save(alert);log.warn("Operational alert generated type={} entity={} severity={}",alert.getType(),alert.getEntityReference(),alert.getSeverity());}else{log.info("Scan event ingested car={} yard={} type={}",event.getCarNumber(),event.getYardCode(),event.getEventType());}return saved;} }